 Transform MakeFace(Transform root){var q=GameObject.CreatePrimitive(PrimitiveType.Quad);q.name="Runtime-only helmet photo";Destroy(q.GetComponent<Collider>());q.transform.SetParent(root,false);q.transform.localPosition=new Vector3(0,.57f,-.333f);q.transform.localScale=new Vector3(.455f,.365f,1);q.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Orbit/HelmetPhoto"));q.SetActive(false);return q.transform;}
 public void AttachCrewAvatar(Transform root){if(gleam!=null)gleam.SetActive(true);foreach(var t in astronaut.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;astronaut=root;face.SetParent(root,false);face.localPosition=new Vector3(0,.57f,-.333f);face.localScale=new Vector3(.455f,.365f,1);var g=root.Find("Visor gleam");gleam=g!=null?g.gameObject:null;foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=29;ApplySelection();}
 Profile Active{get{return roster.Count==0?null:roster[Mathf.Clamp(selected,0,roster.Count-1)];}}
 void BeginPick(bool add){if(pickerOpen)return;adding=add||roster.Count==0;managerOpen=true;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;try{pickerOpen=hp_begin_pick()==1;if(!pickerOpen)message="Could not open the macOS chooser.";}catch(Exception){message="Local chooser requires macOS player or macOS Unity Editor.";}}
 Texture2D Decode(string path){string ext=Path.GetExtension(path).ToLowerInvariant();if(ext!=".png"&&ext!=".jpg"&&ext!=".jpeg")throw new Exception("Choose PNG, JPG or JPEG.");var info=new FileInfo(path);if(!info.Exists||info.Length==0||info.Length>20*1024*1024)throw new Exception("Choose a readable image under 20 MB.");int w,h,valid=hp_image_info(path,out w,out h);if(valid==-2)throw new Exception("Image limit: 8192 per side, 24 megapixels.");if(valid!=1)throw new Exception("That file is not a readable PNG or JPEG.");var tex=new Texture2D(2,2,TextureFormat.RGBA32,false);try{if(!ImageConversion.LoadImage(tex,File.ReadAllBytes(path),true))throw new Exception("Image decoding failed.");if(Mathf.Max(tex.width,tex.height)>2048){float ratio=2048f/Mathf.Max(tex.width,tex.height);int tw=Mathf.Max(1,Mathf.RoundToInt(tex.width*ratio)),th=Mathf.Max(1,Mathf.RoundToInt(tex.height*ratio));var rt=RenderTexture.GetTemporary(tw,th,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;Graphics.Blit(tex,rt);RenderTexture.active=rt;var down=new Texture2D(tw,th,TextureFormat.RGBA32,false);down.ReadPixels(new Rect(0,0,tw,th),0,0);down.Apply(false,true);RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Destroy(tex);tex=down;}tex.wrapMode=TextureWrapMode.Clamp;tex.filterMode=FilterMode.Bilinear;return tex;}catch{Destroy(tex);throw;}}
 Texture2D Texture(Profile p){if(p==null)return null;Texture2D t;if(textures.TryGetValue(p,out t))return t;try{t=Decode(p.path);textures[p]=t;return t;}catch{message="A roster image is no longer readable. Choose a replacement.";return null;}}
 void TrimTextures(){var keep=new HashSet<Profile>();for(int i=0;i<Mathf.Min(4,roster.Count);i++)keep.Add(roster[(selected+i)%roster.Count]);var remove=new List<Profile>();foreach(var kv in textures)if(!keep.Contains(kv.Key)){Destroy(kv.Value);remove.Add(kv.Key);}foreach(var p in remove)textures.Remove(p);}
 void Load(string path){try{var tex=Decode(path);Profile p;if(adding||Active==null){p=new Profile{name="CREW "+(roster.Count+1).ToString("D2"),path=path};roster.Add(p);selected=roster.Count-1;}else{p=Active;Texture2D old;if(textures.TryGetValue(p,out old)){Destroy(old);textures.Remove(p);}p.path=path;p.zoom=1;p.panX=p.panY=.5f;p.turns=0;}p.width=tex.width;p.height=tex.height;textures[p]=tex;ApplySelection();message="Photo loaded locally. Crop the actual helmet preview. Enter finishes.";previewOpen=true;Evidence("selected");}catch(Exception e){message=e is IOException||e is UnauthorizedAccessException?"Could not read that file. Existing crew is unchanged.":e.Message;Evidence("error");}}
 void SetMaterial(Material material,Profile p,Texture2D tex){if(p==null||tex==null)return;float aspect=p.turns%2==0?(float)tex.width/tex.height:(float)tex.height/tex.width,target=.455f/.365f,w=aspect>target?target/aspect:1,h=aspect>target?1:aspect/target;w/=p.zoom;h/=p.zoom;material.SetTexture("_MainTex",tex);material.SetVector("_Crop",new Vector4((1-w)*p.panX,(1-h)*p.panY,w,h));material.SetFloat("_Turns",p.turns);}
 void ApplySelection(){if(face==null)return;TrimTextures();var p=Active;var t=Texture(p);face.gameObject.SetActive(t!=null);if(gleam!=null)gleam.SetActive(t==null);if(t!=null)SetMaterial(faceMaterial,p,t);else faceMaterial.SetTexture("_MainTex",Texture2D.whiteTexture);}
 public void BindCompanion(Transform root,int offset){if(roster.Count<=offset){var emptyFace=root.Find("Runtime-only helmet photo");if(emptyFace!=null)emptyFace.gameObject.SetActive(false);var emptyVisor=root.Find("Visor gleam");if(emptyVisor!=null)emptyVisor.gameObject.SetActive(true);root.name="Surface crew companion "+offset;Material emptyMaterial;if(companionMaterials.TryGetValue(root,out emptyMaterial))emptyMaterial.SetTexture("_MainTex",Texture2D.whiteTexture);return;}var p=roster[(selected+offset)%roster.Count];root.name=p.name;var tex=Texture(p);var patch=root.Find("Runtime-only helmet photo");if(patch==null)patch=MakeFace(root);Material mat;if(!companionMaterials.TryGetValue(root,out mat)){mat=new Material(Shader.Find("Orbit/HelmetPhoto"));companionMaterials[root]=mat;patch.GetComponent<Renderer>().sharedMaterial=mat;}patch.gameObject.SetActive(tex!=null);var g=root.Find("Visor gleam");if(g!=null)g.gameObject.SetActive(tex==null);if(tex!=null)SetMaterial(mat,p,tex);}
 void Remove(){if(Active==null)return;var p=Active;Texture2D old;if(textures.TryGetValue(p,out old)){Destroy(old);textures.Remove(p);}roster.RemoveAt(selected);selected=Mathf.Clamp(selected,0,Mathf.Max(0,roster.Count-1));ApplySelection();message="Profile removed from memory. Other roster entries are retained.";Evidence("removed");}
 void Update(){if(!ready||AutomatedPlayback)return;if(pickerOpen){int s=hp_pick_status();if(s==2){string path=Marshal.PtrToStringUTF8(hp_pick_path());hp_clear_result();pickerOpen=false;Load(path);Input.ResetInputAxes();}else if(s==3){hp_clear_result();pickerOpen=false;message="Selection cancelled; roster and crops unchanged.";Evidence("cancel");Input.ResetInputAxes();}return;}
  if(Input.GetKeyDown(KeyCode.H)&&!managerOpen){managerOpen=true;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;if(roster.Count==0)BeginPick(true);}
  if(!managerOpen)return;bool naming=namingFocus;if(!naming){if(Input.GetKeyDown(KeyCode.N))BeginPick(true);if(Input.GetKeyDown(KeyCode.C))BeginPick(false);if(roster.Count>0&&(Input.GetKeyDown(KeyCode.PageDown)||Input.GetKeyDown(KeyCode.PageUp))){selected=(selected+(Input.GetKeyDown(KeyCode.PageDown)?1:roster.Count-1))%roster.Count;scroll.y=selected*45;ApplySelection();Evidence("selection");}for(int i=0;i<Mathf.Min(9,roster.Count);i++)if(Input.GetKeyDown((KeyCode)((int)KeyCode.Alpha1+i))){selected=i;ApplySelection();Evidence("selection");}var p=Active;if(p!=null){if(Input.GetKeyDown(KeyCode.Z))p.zoom=Mathf.Min(3,p.zoom+.2f);if(Input.GetKeyDown(KeyCode.X))p.zoom=Mathf.Max(1,p.zoom-.2f);if(Input.GetKeyDown(KeyCode.T)){p.turns=(p.turns+1)%4;Evidence("rotated");}if(Input.GetKeyDown(KeyCode.Alpha0)){p.zoom=1;p.panX=p.panY=.5f;p.turns=0;Evidence("crop-reset");}if(Input.GetKeyDown(KeyCode.LeftArrow))p.panX=Mathf.Max(0,p.panX-.05f);if(Input.GetKeyDown(KeyCode.RightArrow))p.panX=Mathf.Min(1,p.panX+.05f);if(Input.GetKeyDown(KeyCode.UpArrow))p.panY=Mathf.Min(1,p.panY+.05f);if(Input.GetKeyDown(KeyCode.DownArrow))p.panY=Mathf.Max(0,p.panY-.05f);if(Input.GetKeyDown(KeyCode.Backspace)||Input.GetKeyDown(KeyCode.Delete))Remove();ApplySelection();}}
  if(Input.GetKeyDown(KeyCode.Return)||Input.GetKeyDown(KeyCode.Escape)){managerOpen=false;clearFocus=true;Input.ResetInputAxes();Evidence("applied");}
 }
