  if(!managerOpen){if(Button(new Rect(42,96,245,32),"H  /  CREW PORTRAITS  ("+roster.Count+")")){managerOpen=true;if(roster.Count==0)BeginPick(true);}if(previewOpen&&roster.Count>0){Panel(new Rect(1300,180,255,358));Text(new Rect(1313,192,228,27),SelectedName,small);GUI.DrawTexture(new Rect(1315,226,225,270),preview,ScaleMode.ScaleToFit,false);if(Button(new Rect(1315,500,225,27),"Hide crew preview"))previewOpen=false;}return;}
  Panel(new Rect(140,155,1320,640));Text(new Rect(168,175,1000,40),"CREW / LOCAL PORTRAITS",title);Text(new Rect(168,221,1190,42),message,small);
  Rect list=new Rect(168,275,275,410);scroll=GUI.BeginScrollView(list,scroll,new Rect(0,0,250,Mathf.Max(410,roster.Count*45)));int start=Mathf.Max(0,(int)(scroll.y/45)),end=Mathf.Min(roster.Count,start+11);for(int i=start;i<end;i++){if(Button(new Rect(0,i*45,247,39),(i==selected?"● ":"")+(i+1)+"  "+roster[i].name)){selected=i;ApplySelection();Evidence("selection");}}GUI.EndScrollView();
