   if(Button(new Rect(850,553,170,40),"T / Rotate 90°")){p.turns=(p.turns+1)%4;Evidence("rotated");}if(Button(new Rect(1038,553,170,40),"C / Replace photo"))BeginPick(false);if(Button(new Rect(1226,553,175,40),"Delete / Remove"))Remove();ApplySelection();
  }
