 void Evidence(string step){if(qa){Debug.Log("CREW_QA "+step+" count="+roster.Count+" selected="+selected);StartCoroutine(Shot(step));}}
 IEnumerator Shot(string step){yield return new WaitForEndOfFrame();yield return new WaitForEndOfFrame();string dir=Environment.GetEnvironmentVariable("BH_EVIDENCE");if(string.IsNullOrEmpty(dir))yield break;Directory.CreateDirectory(dir);ScreenCapture.CaptureScreenshot(Path.Combine(dir,"crew-"+step+".png"));File.WriteAllText(Path.Combine(dir,"crew-"+step+".json"),"{\"event\":\""+step+"\",\"rosterCount\":"+roster.Count+",\"selected\":"+selected+",\"cachedTextures\":"+textures.Count+",\"runtimeOnly\":true}");}
 public Dictionary<string,bool> CheckLocalRoster(string fixtures){
  var checks=new Dictionary<string,bool>();var first=roster[0];var second=roster[1];selected=0;first.zoom=1.8f;first.panX=.2f;first.turns=1;ApplySelection();var crop=faceMaterial.GetVector("_Crop");checks["crop_updates_actual_visor_material"]=crop.z<.8f&&faceMaterial.GetFloat("_Turns")==1;
  selected=1;ApplySelection();checks["selection_has_independent_crop"]=Active==second&&second.zoom==1&&faceMaterial.GetFloat("_Turns")==0;selected=0;ApplySelection();checks["reselection_preserves_crop"]=faceMaterial.GetVector("_Crop")==crop;
  int count=roster.Count;string path=first.path;var texture=faceMaterial.GetTexture("_MainTex");adding=false;Load(Path.Combine(fixtures,"corrupt.png"));checks["corrupt_replacement_preserves_profile"]=roster.Count==count&&Active==first&&first.path==path&&faceMaterial.GetTexture("_MainTex")==texture;
  selected=roster.Count-1;Remove();checks["remove_keeps_other_profiles"]=roster.Count==count-1&&roster.Contains(first);bool bounded=true;for(int i=0;i<roster.Count;i++){selected=i;ApplySelection();bounded&=textures.Count<=4;}checks["roster_selection_eviction_stays_bounded"]=bounded;
  adding=true;Load(Path.Combine(fixtures,"large-valid.png"));var large=Texture(Active);checks["large_valid_photo_downsamples"]=large!=null&&Mathf.Max(large.width,large.height)==2048;Remove();selected=0;ApplySelection();return checks;
 }
 void OnDestroy(){foreach(var t in textures.Values)Destroy(t);foreach(var m in companionMaterials.Values)Destroy(m);if(faceMaterial!=null)Destroy(faceMaterial);if(previewCam!=null)Destroy(previewCam.gameObject);if(preview!=null){preview.Release();Destroy(preview);}if(current==this)current=null;}
